import {
  Group, Mesh, Shape, ShapeGeometry, CircleGeometry, CylinderGeometry,
  MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial,
  Color, Vector2, Vector3, Object3D
} from 'three/webgpu';
import { uv, vec3, mix, uniform, distance, smoothstep, time, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Parse items: three groups of 3 items each
  const cardData = [];
  for (let i = 0; i < 3; i++) {
    const offset = i * 3;
    cardData.push({
      icon: items[offset]?.text ?? '',
      title: items[offset + 1]?.text ?? '',
      body: items[offset + 2]?.text ?? ''
    });
  }

  // Card dimensions
  const cardW = 1.5;
  const cardH = 1.9;
  const cornerRadius = 0.06;
  const borderWidth = 0.006;
  const gap = 0.25;
  const totalWidth = cardW * 3 + gap * 2;
  const startX = -totalWidth / 2 + cardW / 2;

  // Create a rounded rect shape
  function createRoundedRectShape(w, h, r) {
    const shape = new Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    return shape;
  }

  // Gradient material for card front
  const topColor = uniform(new Color('#191921'));
  const bottomColor = uniform(new Color('#121218'));
  const gradientNode = mix(topColor, bottomColor, uv().y);
  const cardMaterial = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.25,
    clearcoat: 0.15
  });
  cardMaterial.colorNode = gradientNode;

  // Border material
  const borderMaterial = new MeshBasicNodeMaterial({ color: '#26262f' });

  // Disc material
  const discMaterial = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    anisotropy: 0.6
  });

  // Text material for icon (emissive)
  const iconMaterial = new MeshPhysicalNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.6
  });

  // Contact shadow material
  const shadowOpacity = uniform(0.5);
  const shadowRadius = 0.8;
  const shadowNode = smoothstep(0.0, shadowRadius, distance(uv().xy * 2.0 - 1.0, vec2(0, 0)));
  const shadowColor = vec3(0, 0, 0);
  const shadowMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacityNode: shadowOpacity,
    colorNode: mix(shadowColor, vec3(0, 0, 0, 0), shadowNode) // mixed with transparent
  });

  // Helper to create text mesh with specific material
  function createTextMesh(content, fontSize, materialOverride) {
    const textObj = ctx.fontAtlas.createText(content, {
      fontSize: fontSize,
      color: '#ffffff',
      align: 'center'
    });
    // Replace material with custom if provided
    if (materialOverride) {
      textObj.traverse(child => {
        if (child.isMesh) {
          child.material = materialOverride;
        }
      });
    }
    return textObj;
  }

  // Create the main group
  const root = new Group();
  root.userData.cleanup = () => {};
  const cleanupFns = [];
  const timelines = [];

  // Create cards
  const cardGroups = [];
  cardData.forEach((data, index) => {
    const cardGroup = new Group();
    const xPos = startX + index * (cardW + gap);
    cardGroup.position.set(xPos, 0, 0);

    // Border plane (slightly larger)
    const borderShape = createRoundedRectShape(cardW + borderWidth * 2, cardH + borderWidth * 2, cornerRadius + borderWidth);
    const borderGeo = new ShapeGeometry(borderShape);
    const borderMesh = new Mesh(borderGeo, borderMaterial);
    borderMesh.position.z = -0.005;
    cardGroup.add(borderMesh);

    // Front card plane (gradient)
    const cardShape = createRoundedRectShape(cardW, cardH, cornerRadius);
    const cardGeo = new ShapeGeometry(cardShape);
    const cardMesh = new Mesh(cardGeo, cardMaterial);
    cardGroup.add(cardMesh);

    // Contact shadow plane (under card, behind)
    const shadowGeo = new CircleGeometry(0.6, 32);
    const shadowMesh = new Mesh(shadowGeo, shadowMaterial);
    shadowMesh.position.z = -0.015;
    shadowMesh.scale.set(1, 1, 1);
    shadowMesh.material.opacity = 0.4;
    cardGroup.add(shadowMesh);

    // Icon seat disc
    const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 32);
    const discMesh = new Mesh(discGeo, discMaterial);
    discMesh.position.set(0, 0.5, 0.01); // icon seat at y = 0.5 (relative to card center? we'll adjust)
    // Actually we need to position within card: interior padding 0.375 from top? Let's compute.
    // Card height 1.9, padding 0.375 from each side? The spec says "interior padding 0.375 (1.5x base)". So content area starts at y = 0.375 from top? We'll center the icon at y = 0.5 from center? Let's approximate: top of card is at y=0.95, padding 0.375 from top -> y=0.575. Icon seat diameter 0.4, so center at y=0.575 - 0.2? Actually easier: we'll place icon seat at y = 0.5 (above center) and then text below. We'll adjust.
    discMesh.position.y = 0.5;
    cardGroup.add(discMesh);

    // Icon glyph
    const iconText = createTextMesh(data.icon, 20, iconMaterial);
    iconText.position.set(0, 0.5, 0.02); // slightly above disc
    iconText.scale.set(0.5, 0.5, 0.5); // scale to match 20px? Actual font size is 20, but we need to adjust size in scene units. We'll keep default.
    cardGroup.add(iconText);

    // Title text
    const titleText = createTextMesh(data.title, 20, null); // use default material
    titleText.position.set(0, -0.2, 0.01);
    titleText.scale.set(0.8, 0.8, 0.8); // scale to fit
    cardGroup.add(titleText);

    // Body text
    const bodyText = createTextMesh(data.body, 13, null);
    bodyText.position.set(0, -0.5, 0.01);
    bodyText.scale.set(0.6, 0.6, 0.6);
    cardGroup.add(bodyText);

    // Store references for hover
    cardGroup.userData = {
      cardMesh,
      shadowMesh,
      discMesh,
      iconText,
      titleText,
      bodyText,
      handlers: {
        pointerenter: () => {
          // Lift
          const tl = gsap.timeline({ paused: true });
          tl.to(cardGroup.position, {
            y: 0.06,
            z: 0.12,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
          tl.to(shadowMesh.scale, {
            x: 1.3,
            y: 1.3,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
          tl.to(shadowMesh.material, {
            opacity: 0.6,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
          tl.to(iconMaterial.emissiveIntensity, {
            value: 2.2,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
          tl.play();
          timelines.push(tl);
        },
        pointerleave: () => {
          const tl = gsap.timeline({ paused: true });
          tl.to(cardGroup.position, {
            y: 0,
            z: 0,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
          tl.to(shadowMesh.scale, {
            x: 1,
            y: 1,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
          tl.to(shadowMesh.material, {
            opacity: 0.4,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
          tl.to(iconMaterial.emissiveIntensity, {
            value: 1.6,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
          tl.play();
          timelines.push(tl);
        }
      }
    };

    cardGroups.push(cardGroup);
    root.add(cardGroup);
  });

  // Stagger entrance animation
  const entranceTL = gsap.timeline();
  cardGroups.forEach((card, i) => {
    entranceTL.fromTo(card.position, {
      y: card.position.y + 0.2,
      opacity: 0
    }, {
      y: card.position.y,
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, i * 0.08);
  });
  timelines.push(entranceTL);

  // Cleanup function
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    // Dispose materials and geometries
    [borderMaterial, cardMaterial, discMaterial, iconMaterial, shadowMaterial].forEach(mat => {
      if (mat) mat.dispose();
    });
    root.traverse(child => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
      }
    });
    // Remove all children
    while (root.children.length) {
      root.remove(root.children[0]);
    }
  };

  // Set root event handlers (empty, but required)
  root.userData.handlers = {};

  return root;
}
